    public static final Map<String, List<TagKey<Block>>> BLOCK_TAGS = new HashMap<>();

    private static TagKey<Block> createTag(String nameSpace, String path){
        return TagKey.create(ForgeRegistries.BLOCKS.getRegistryKey(), ResourceLocation.tryBuild(nameSpace, path));
    }

    private static TagKey<Block> createTagQuark(String path){ // quark
        return createTag(Quark.MOD_ID, path);
    }

    private static TagKey<Block> createTag(String path){ // minecraft
        return createTag(ResourceLocation.DEFAULT_NAMESPACE, path);
    }

